# typed: false
# frozen_string_literal: true

# Homebrew formula for CERT-X-GEN (cxg)
# A polyglot execution engine for vulnerability detection
#
# Generated by .github/workflows/update-formula.yml on each cert-x-gen
# release. Edit the workflow, not this file -- a hand edit here is
# overwritten by the next release.
class Cxg < Formula
  desc "Polyglot execution engine for vulnerability detection"
  # @comment -- "brew info / brew home open the cxg product site, cxg.bugb.io"
  homepage "https://cxg.bugb.io"
  version "1.6.0"
  license "Apache-2.0"

  on_macos do
    on_intel do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.0/cxg-darwin-amd64"
      sha256 "3bdfbe694bae2d57becd42bf5be27dcd09bcc7b7293f7eac4e7db17a847d4b4f"
    end
    on_arm do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.0/cxg-darwin-arm64"
      sha256 "a0fe5af83cfd505e98dada5242efbfdbe45c9820286cbcd97ba28897df1f6c73"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.0/cxg-linux-amd64"
      sha256 "4e743c0e263a10477515a821c7c5ee9600df9f3c1fc924c0752697daa55f8c90"
    end
    on_arm do
      url "https://github.com/Bugb-Technologies/cert-x-gen/releases/download/v1.6.0/cxg-linux-arm64"
      sha256 "2119e7408cce6dbb354cf57b42f8c05b2542b028b294a222f4d84b2f4e3fad31"
    end
  end

  def install
    bin.install Dir["cxg-*"].first => "cxg"
  end

  # Templates are fetched at first use, not at install time. Running
  # `cxg template update` from post_install writes outside the formula
  # prefix, which Homebrew's install sandbox denies -- it failed the
  # install rather than the download. Tell the user instead.
  def caveats
    <<~EOS
      To download vulnerability detection templates, run:
        cxg template update

      Templates will be installed to ~/.cert-x-gen/templates/
    EOS
  end

  test do
    assert_match "cxg", shell_output("#{bin}/cxg --version")
  end
end
